/* V15: fan-supplied concert memories. Stage dialogue remains game fiction. */
function letterShelf(){return `<section class="letter-shelf"><span class="eyebrow">THE FINAL LETTERS</span><h3>네 사람이 남긴 마지막 편지</h3><div class="letter-tabs"><button onclick="readConcertLetter('yechan',3)">${animalMark(0)} 예찬 막콘 편지 ↗</button><button onclick="readConcertLetter('sangyeop',3)">${animalMark(1)} 상엽 막콘 편지 ↗</button><button onclick="readStageLetter('wonsang')">${animalMark(2)} 원상 막콘 편지 ↗</button><button onclick="readStageLetter('gwangil')">${animalMark(3)} 광일 막콘 편지 ↗</button></div></section>`}

function readConcertLetter(who,day){const x=CONCERT_LETTERS[who]?.find(x=>x.day===day);if(!x)return;modal(`<article class="concert-letter membervoice-${who==='yechan'?0:1}"><span class="eyebrow">TO. WALWAL / DAY ${day}</span><h2>${who==='yechan'?'예찬':'상엽'}의 편지</h2><div class="letter-original">${esc(x.body)}</div><button class="secondary" onclick="concertLetters()">편지 모아보기 ←</button></article>`)}
function concertLetters(){modal(letterShelf())}
const albumBeforeFanlove=album;album=function(){albumBeforeFanlove();$('#modalbody').innerHTML+=letterShelf()};
const farewellBeforeFanlove=farewellView;
farewellView=function(){let html=farewellBeforeFanlove();html=html.replace(/<p class="lettercaption">[\s\S]*?<\/p>/,'<p class="lettercaption">공연의 마지막에 남긴 마음을 다시 읽어본다.</p>'+letterShelf());return html};
function bridgePicker(){return `<section class="bridge-picker"><span class="eyebrow">ONE MORE SCENE / OPTIONAL</span><h3>팬들이 알아볼, 그 연결</h3>${thoughtBox('끝을 닮은 선율을 다시 꺼낼까… 다음 곡을 알아채는 함성이 먼저 들려올지도.')}<p class="fine">기본 13곡은 그대로 · 연결 무대 최대 1개 · 실제 체력과 공연 시간 추가</p><div class="bridge-options">${FAN_BRIDGES.map(b=>{const active=S.bridge===b.id,available=!b.target||S.set.some(id=>track(id).title===b.target);return `<button class="${active?'bridge-active':''}" onclick="act('planBridge','${b.id}')" ${available?'':'disabled'} aria-pressed="${active}"><b>${b.title}</b>${keywords(b.traits)}${metricChips(['예산 −'+b.budget,'시간 −'+b.time])}<small>${active?'선택됨':available?'공연 +'+b.minutes+'분':b.target+' 선곡 시 가능'}</small></button>`}).join('')}</div><button class="textbtn" onclick="act('planBridge','none')">연결 무대 비우기 · 해당 준비 자원 반환</button></section>`}
const reviewBeforeFanlove=reviewView;reviewView=function(){return bridgePicker()+reviewBeforeFanlove()};
const songCardBeforeFanlove=songCard;songCard=function(x,encore=false){const html=songCardBeforeFanlove(x,encore);return FAN_CALL_SONGS.includes(x.title)?html.replace('</h3></div><div class="songtraits">','</h3><span class="fan-call-badge" aria-label="응원법이 있는 곡">💙 응원법</span></div><div class="songtraits">'):html};
function fanEchoes(){if(!S)return [];const a=[];if(S.picks.concept==='return'&&S.picks.arrange==='outro')a.push('처음 정한 ‘돌아오는 섬’의 선율을 마지막까지 남겼다.');if(S.special==='blind')a.push('안대를 쓰기 전의 동선 점검이 무대 위 예찬의 자리를 지켰다.');if(S.special==='pass'&&S.set.some(id=>track(id).title==='카멜레온'))a.push('두 악기만 남았던 파사칼리아가 카멜레온으로 이어졌다.');if(S.fixed.includes('신곡 합주'))a.push('원상과 함께 확인한 합주의 연결이 첫 곡을 받쳤다.');if(S.techProgress>=10)a.push('광일이 챙겨온 장비와 Cue 점검이 공연의 바닥을 단단하게 만들었다.');if(S.incidentSeen.includes('choir'))a.push('「'+S.choirSong+'」에서 기다려준 객석의 목소리를 들었다.');if(S.bridge)a.push(FAN_BRIDGES.find(x=>x.id===S.bridge).title+' · 추가로 준비한 선율을 무대에 남겼다.');return a}
const resultBeforeFanlove=result;result=function(){const a=fanEchoes();return resultBeforeFanlove().replace('<div class="resultactions">',(a.length?`<section class="fan-keepsakes"><span class="eyebrow">ONLY OUR CONCERT</span><h3>우리가 만든 장면들</h3>${a.map(t=>'<p>✦ '+esc(t)+'</p>').join('')}</section>`:'')+letterShelf()+'<div class="resultactions">')};
const liveTextBeforeFanlove=liveText;liveText=function(item){if(item.kind==='bridge'){const b=Game.itemTrack(item,S);return b.target?'다음 곡의 이름을 말하기 전에, 익숙한 선율을 먼저 건넨다. 알아챈 객석에서 함성이 올라온다.':b.id==='intro'?'독립 연주곡 INTRO의 선율을, 다시! 다음 장면에 펼친다. 이번 섬의 길이 조금 더 넓어진다.':'마지막 노래 뒤에 독립 연주곡 OUTRO를 남긴다. 목소리가 멎은 자리에서도 선율이 조금 더 머문다.'}let t=liveTextBeforeFanlove(item);const x=Game.itemTrack(item,S);if(FAN_CALL_SONGS.includes(x.title))t+=' 익숙한 응원법이 돌아오는 구간, 네 사람도 객석의 박자에 귀를 기울인다.';return t};
const incidentViewBeforeFanlove=incidentView;incidentView=function(){return (S.incident==='choir'?`<div class="choir-song-label">💙 지금 객석이 부르는 노래 · ${esc(S.choirSong)}</div>`:'')+incidentViewBeforeFanlove()};
function readStageLetter(who){const x=STAGE_LETTERS[who];if(!x)return;modal(`<article class="concert-letter"><span class="eyebrow">THE FINAL DAY / TO. WALWAL</span><h2>${x.name}의 막콘 편지</h2><div class="letter-original">${esc(x.body)}</div><button class="secondary" onclick="concertLetters()">편지 모아보기 ←</button></article>`)}
function stageHeart(){return `<section class="stage-heart"><span class="eyebrow">THE HEART WE LEFT ON STAGE</span><h3>무대에 남은 마음</h3><p class="heart-intro">찾아와 준 사람들 덕분에 빛났던 무대.<br>사랑을 주고받기 위해 이어온 음악.</p>${STAGE_HEART_EXCERPTS.map(x=>`<blockquote>${esc(x.text)}</blockquote>`).join('')}</section>`}
function readStageSpeech(){modal(stageHeart()+`<button class="secondary" onclick="concertLetters()">편지 모아보기 ←</button>`)}
const farewellBeforeHeart=farewellView;farewellView=function(){return farewellBeforeHeart()+stageHeart()};

render();

const liveBeforeFanlove=live;live=function(){const item=S.queue[S.cursor],x=Game.itemTrack(item,S);const response=item.kind==='track'&&FAN_CALL_SONGS.includes(x.title)?`<section class="fan-response"><b>💙 왈왈이 응원법이 있는 곡</b><p>연주와 가창은 그대로 이어가며, 응답 구간에서 객석과 눈을 맞춘다.</p><button class="secondary" onclick="act('playMain',{call:true})" ${(S.callCount||0)>=3||!Game.canPlay(S,item)?'disabled':''}>응원법에 응답하며 진행 · 관객 +1</button><small>공연당 3회 · 남은 응답 ${Math.max(0,3-(S.callCount||0))}회 · 곡의 체력·시간 그대로 소모</small></section>`:'';return response+liveBeforeFanlove()};

const setListBeforeFanlove=setList;setList=function(){setListBeforeFanlove();if(S?.bridge){const b=FAN_BRIDGES.find(x=>x.id===S.bridge);$('#modalbody').innerHTML+=`<div class="note"><b>추가 연결 · ${b.title}</b><p>${b.traits} · 공연 +${b.minutes}분</p></div>`}};
